INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist unkompilierter Code immer direkt ausführbar?', 2, '[{"text": "Nein", "correct": true, "because": "Muss oft kompiliert oder interpretiert werden"}, {"text": "Ja", "correct": false, "because": "Ignoriert Kompilierungsschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft mir, die Lesbarkeit von Code zu verbessern?', 3, '[{"text": "Code-Formatter", "correct": true, "because": "Standardisiert Einrückungen und Struktur"}, {"text": "Debugger", "correct": false, "because": "Für Fehlersuche, nicht Formatierung"}, {"text": "Compiler", "correct": false, "because": "Erzeugt Maschinencode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praktiken fördern wartbaren Programmcode?', 5, '[{"text": "Modulare Struktur", "correct": true, "because": "Vereinfacht Änderungen"}, {"text": "Kommentierung", "correct": true, "because": "Erklärt Logik"}, {"text": "Maximale Komprimierung", "correct": false, "because": "Schadet Lesbarkeit"}, {"text": "Einzeilige Funktionen", "correct": false, "because": "Oft unübersichtlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kommentare erhöhen die Wartbarkeit. b) Sie beschleunigen die Ausführung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kommentare beeinflussen Laufzeit nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Optimierung von Code für ein Teamprojekt?', 4, '[{"text": "Konsistenter Stil", "correct": false, "because": "Wichtig für Zusammenarbeit"}, {"text": "Versionskontrolle", "correct": false, "because": "Schützt Änderungen"}, {"text": "Persönliche Formatvorlieben", "correct": true, "because": "Teamstandards zählen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Variablennamen die Ausführungsgeschwindigkeit beeinflussen?', 2, '[{"text": "Nein", "correct": true, "because": "Werden beim Kompilieren ignoriert"}, {"text": "Ja", "correct": false, "because": "Nur für Lesbarkeit relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ist entscheidend, um Fehler in einem Programm zu minimieren?', 4, '[{"text": "Testgetriebene Entwicklung", "correct": true, "because": "Sichert Funktionalität früh"}, {"text": "Schnelle Prototypen", "correct": false, "because": "Risiko für Fehler"}, {"text": "Maximale Codezeilen", "correct": false, "because": "Komplexität erhöht Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass lange Funktionen die Wartung erschweren. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Kürzere Funktionen sind übersichtlicher"}, {"text": "Nein", "correct": false, "because": "Länge erhöht Komplexität"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein einheitlicher Codierstil nur für große Teams wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Teams profitieren von Klarheit"}, {"text": "Ja", "correct": false, "because": "Klarheit immer nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich, um Änderungen in einem Programm nachzuverfolgen?', 3, '[{"text": "Git", "correct": true, "because": "Ermöglicht Versionskontrolle"}, {"text": "Texteditor", "correct": false, "because": "Nur für Bearbeitung"}, {"text": "Linter", "correct": false, "because": "Prüft Syntax"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Code nachvollziehbar?', 5, '[{"text": "Klarer Variablennamen", "correct": true, "because": "Beschreibt Zweck"}, {"text": "Strukturierte Module", "correct": true, "because": "Teilt Logik auf"}, {"text": "Minimale Kommentare", "correct": false, "because": "Können unklar lassen"}, {"text": "Hohe Zeilenanzahl", "correct": false, "because": "Erschwert Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Code-Wartung priorisieren?', 4, '[{"text": "Refactoring", "correct": true, "because": "Verbessert Struktur ohne Funktionsänderung"}, {"text": "Schnelles Hinzufügen", "correct": false, "because": "Risiko für Fehler"}, {"text": "Komplettes Neuschreiben", "correct": false, "because": "Oft zu aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Versionskontrolle schützt vor Datenverlust. b) Sie ersetzt automatische Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests prüfen Funktionalität"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Strukturierung eines Programms?', 3, '[{"text": "Logische Aufteilung", "correct": false, "because": "Fördert Wartbarkeit"}, {"text": "Konsistente Formatierung", "correct": false, "because": "Verbessert Lesbarkeit"}, {"text": "Farbschema des Editors", "correct": true, "because": "Kein funktionaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Linter die Logik eines Programms prüft?', 2, '[{"text": "Nein", "correct": true, "because": "Prüft nur Syntax und Stil"}, {"text": "Ja", "correct": false, "because": "Logik ist Sache von Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Code ohne Tests immer unsicher ist. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Tests decken Fehler auf"}, {"text": "Nein", "correct": false, "because": "Tests sind essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Compiler für interpretierte Sprachen nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Interpreter übernimmt Ausführung"}, {"text": "Ja", "correct": false, "because": "Nur für kompilierte Sprachen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verfahren stellt sicher, dass Änderungen die Funktionalität nicht brechen?', 4, '[{"text": "Regressionstests", "correct": true, "because": "Prüft bestehende Funktionen"}, {"text": "Code-Komprimierung", "correct": false, "because": "Verkleinert nur"}, {"text": "Manuelles Debuggen", "correct": false, "because": "Zu fehleranfällig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei der Code-Dokumentation wichtig?', 5, '[{"text": "Beschreibung von Funktionen", "correct": true, "because": "Erklärt Zweck"}, {"text": "Beispiele für Nutzung", "correct": true, "because": "Vereinfacht Verständnis"}, {"text": "Zeilenummerierung", "correct": false, "because": "Kein Dokumentationsfaktor"}, {"text": "Farbliche Hervorhebung", "correct": false, "because": "Nur visuelle Hilfe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei einem neuen Projekt vermeiden?', 3, '[{"text": "Unstrukturierte Funktionen", "correct": true, "because": "Erschweren Wartung"}, {"text": "Versionskontrolle", "correct": false, "because": "Schützt Änderungen"}, {"text": "Automatisierte Tests", "correct": false, "because": "Sichern Qualität"}]');
